#include <stdio.h>

int search(int *nums, int numsSize, int target) {
    int lo = 0, hi = numsSize - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int n, target;
    if (scanf("%d %d", &n, &target) != 2) return 0;
    static int a[100005];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    printf("%d\n", search(a, n, target));
    return 0;
}

#include <stdio.h>

static int lower_bound(int *a, int n, int t) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < t) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main(void) {
    int n, target;
    if (scanf("%d %d", &n, &target) != 2) return 0;
    static int a[100005];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int lo = lower_bound(a, n, target);
    int hi = lower_bound(a, n, target + 1) - 1;
    if (lo <= hi && lo < n && a[lo] == target) printf("%d %d\n", lo, hi);
    else printf("-1 -1\n");
    return 0;
}

